import{_ as e,o as a,c as n,ag as o}from"./chunks/framework.BFM5MFIQ.js";const k=JSON.parse('{"title":"Markdown formatting","description":"Internal links, mentions, tags and Markdown formatting in Owlbear’s DMH.","frontmatter":{"title":"Markdown formatting","description":"Internal links, mentions, tags and Markdown formatting in Owlbear’s DMH.","order":20},"headers":[],"relativePath":"en/reference/markdown.md","filePath":"en/reference/markdown.md"}'),d={name:"en/reference/markdown.md"};function r(i,t,l,c,s,m){return a(),n("div",null,[...t[0]||(t[0]=[o('<h1 id="markdown-formatting" tabindex="-1">Markdown formatting <a class="header-anchor" href="#markdown-formatting" aria-label="Permalink to &quot;Markdown formatting&quot;">​</a></h1><h2 id="internal-links" tabindex="-1">Internal links <a class="header-anchor" href="#internal-links" aria-label="Permalink to &quot;Internal links&quot;">​</a></h2><p>Link to other entities in your campaign with <code>[title](type://id)</code>:</p><ul><li><code>[Note Title](note://123)</code> — link to a note</li><li><code>[Module Name](module://123)</code> — link to a module</li><li><code>[Party Name](party://123)</code> — link to a party</li><li><code>[Pawn Name](pawn://123)</code> — link to a pawn</li><li><code>[Encounter Name](encounter://123)</code> — link to an encounter</li></ul><h2 id="entity-mentions" tabindex="-1">Entity mentions <a class="header-anchor" href="#entity-mentions" aria-label="Permalink to &quot;Entity mentions&quot;">​</a></h2><p>Use the mention buttons in the editor toolbar to link a note, module, party, pawn, or encounter. Mentions use the same internal-link syntax:</p><p><code>[Tavern](note://123)</code> mentions the Tavern note.</p><h2 id="tags" tabindex="-1">Tags <a class="header-anchor" href="#tags" aria-label="Permalink to &quot;Tags&quot;">​</a></h2><p>Type <code>#</code> in the editor to search or create a tag, or write a hashtag directly. Tags are collected in the note options menu.</p><ul><li><code>#tavern</code> adds the “tavern” tag.</li><li><code># Heading</code> headings such as this are not treated as tags.</li></ul><h2 id="markdown" tabindex="-1">Markdown <a class="header-anchor" href="#markdown" aria-label="Permalink to &quot;Markdown&quot;">​</a></h2><p>Basic Markdown formatting:</p><table tabindex="0"><thead><tr><th>Syntax</th><th>Result</th></tr></thead><tbody><tr><td><code>**bold**</code></td><td><strong>Bold text</strong></td></tr><tr><td><code>*italic*</code></td><td><em>Italic text</em></td></tr><tr><td><code># Heading</code></td><td>Section heading</td></tr><tr><td><code>- item</code></td><td>Bullet list</td></tr><tr><td><code>1. item</code></td><td>Numbered list</td></tr><tr><td><code>- [ ] Task item</code> / <code>- [x] Done</code></td><td>Task list with checkboxes</td></tr></tbody></table><p>Task lists written as <code>- [ ]</code> or <code>- [x]</code> render as disabled checkboxes.</p>',14)])])}const u=e(d,[["render",r]]);export{k as __pageData,u as default};
